def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 70:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(bid)
                    if opp.get('budget', 0) > 0:
                        strong_prev_bids.append(bid)

    slots = max(1, int(supply / WATER_REQ))
    scarcity = 1.0 if slots <= 1 else 0.0
    crowded = len(alive) >= slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    practical_prev = max(strong_prev_bids) if strong_prev_bids else highest_prev

    if len(alive) == 0:
        return max(0.0, min(budget, 18.0))

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2
    if budget < 40:
        danger += 1

    if scarcity and crowded:
        if danger >= 5:
            bid = max(78.0, practical_prev + 2.0)
        elif danger >= 3:
            bid = max(66.0, min(79.0, practical_prev + 1.5))
        else:
            if practical_prev >= 78.0:
                bid = 44.0
            else:
                bid = max(52.0, practical_prev + 1.0)
    else:
        if danger >= 5:
            bid = 58.0
        elif danger >= 3:
            bid = 42.0
        else:
            bid = 24.0

    if supply >= 24:
        bid *= 0.72
    elif supply >= 22:
        bid *= 0.82
    elif supply <= 16:
        bid *= 1.12

    if urgent_opp >= 2 and scarcity:
        bid *= 1.08

    if rich_opp <= 1 and hp >= 6 and no_water == 0:
        bid *= 0.9

    if day >= 8 and hp >= 5 and budget < 120:
        bid *= 0.88

    if budget <= 0:
        return 0.0

    reserve = 0.0
    if hp >= 5:
        reserve = 18.0
    elif hp >= 3:
        reserve = 8.0

    max_affordable = max(0.0, budget - reserve)
    if danger >= 5:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)

    if budget < 25 and danger <= 2:
        bid = min(bid, 12.0)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    alive_opponents = []
    for agent_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            opp_data['agent_id'] = agent_id
            alive_opponents.append(opp_data)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    bob_prev_bid = 0.0

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
            if opp['agent_id'] == "Bob":
                bob_prev_bid = prev['bid']

    num_water_slots = int(day_context['supply'] // WATER_REQ)
    num_active_players = len(alive_opponents) + 1

    if num_active_players > num_water_slots:
        base_bid_multiplier = 0.75
    else:
        base_bid_multiplier = 0.55

    bid_value = DAILY_SALARY * base_bid_multiplier

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if bob_prev_bid > 0 and bob_prev_bid >= DAILY_SALARY * 0.7:
            bid_value = max(bid_value, bob_prev_bid + 2.0)
        elif highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 3:
                bid_value = max(bid_value, DAILY_SALARY * 0.95)
            else:
                bid_value = max(bid_value, highest_prev_bid + 1.0)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            bid_value = max(bid_value, highest_prev_bid + 1.0)
        else:
            bid_value = max(bid_value, DAILY_SALARY * 0.6)

    if my_status['hp'] <= 2:
        bid_value = max(bid_value, DAILY_SALARY * 0.98)
    elif my_status['hp'] <= 4:
        bid_value = max(bid_value, DAILY_SALARY * 0.85)

    final_bid = min(my_status['budget'], bid_value)

    if my_status['budget'] > 0:
        final_bid = max(final_bid, DAILY_SALARY * 0.1)
    else:
        final_bid = 0.0

    return final_bid
